1	import { Room } from "@colyseus/sdk";
2	import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
3	import { DUEL_INPUT, duelistMoveset } from "@pirate-sea-race/content/moves";
4	import { DuelMessageType, type DuelProbe } from "@pirate-sea-race/protocol";
5	import { createDuelState, defaultDuelConfig, duelInput, stepDuel, type DuelState } from "@pirate-sea-race/simulation/duel";
6	import { DuelRollback, type DuelFeedEvent } from "@pirate-sea-race/simulation/netcode";
7	import { applyDevLatency, DelayLine, devLatencyFromQuery, type DelaySource } from "./devLatency.js";
8	import { ArenaFlashes, PendingDuelEvents } from "./duelEvents.js";
9	import { renderDuelHud, resultText, roundClock, type DuelHudModel } from "./duelHud.js";
10	import { duelBits, DuelKeyboard } from "./duelKeyboard.js";
11	
12	describe("duel keyboard", () => {
13	  it("maps §8's keys: WASD or arrows, J, K, U, I and Shift", () => {
14	    expect(duelBits(["KeyA", "ArrowRight", "KeyW", "ArrowDown"])).toBe(DUEL_INPUT.left | DUEL_INPUT.right | DUEL_INPUT.up | DUEL_INPUT.down);
15	    expect(duelBits(["KeyJ", "KeyK", "KeyU", "KeyI", "ShiftRight"])).toBe(
16	      DUEL_INPUT.light | DUEL_INPUT.heavy | DUEL_INPUT.special1 | DUEL_INPUT.special2 | DUEL_INPUT.dash,
17	    );
18	    expect(duelBits(["KeyE", "Space"])).toBe(0);
19	  });
20	
21	  it("keeps a tap released before any frame was tagged until one is", () => {
22	    const keyboard = new DuelKeyboard(new EventTarget() as unknown as Window);
23	    keyboard.press("KeyJ");
24	    keyboard.release("KeyJ");
25	    expect(keyboard.bits()).toBe(DUEL_INPUT.light);
26	    expect(keyboard.bits()).toBe(DUEL_INPUT.light);
27	    keyboard.framesTagged();
28	    expect(keyboard.bits()).toBe(0);
29	    // A held key stays in after the frame that took it.
30	    keyboard.press("KeyD");
31	    keyboard.framesTagged();
32	    expect(keyboard.bits()).toBe(DUEL_INPUT.right);
33	  });
34	});
35	
36	describe("duel HUD", () => {
37	  it("counts the round clock down to 0 on the round's last frame, then shows overtime", () => {
38	    expect(roundClock(0, 3600, 600)).toEqual({ seconds: 60, overtime: false });
39	    expect(roundClock(3599, 3600, 600)).toEqual({ seconds: 1, overtime: false });
40	    expect(roundClock(3600, 3600, 600)).toEqual({ seconds: 0, overtime: false });
41	    expect(roundClock(3601, 3600, 600)).toEqual({ seconds: 10, overtime: true });
42	    expect(roundClock(4200, 3600, 600)).toEqual({ seconds: 0, overtime: true });
43	  });
44	
45	  it("words the result", () => {
46	    expect(resultText(0, "timeout")).toBe("Player 1 wins by time");
47	    expect(resultText(1, "forfeit")).toBe("Player 2 wins by forfeit");
48	    expect(resultText(-1, "double-ko")).toBe("Draw (double KO)");
49	    expect(resultText(-1, "forfeit")).toBe("Both forfeit: no winner");
50	  });
51	
52	  it("shows both fighters' stamina from the confirmed state, as a number and a filled share", () => {
53	    const { rules } = duelistMoveset;
54	    // Player one dashes: the confirmed state after the frame has spent the dash's stamina.
55	    const dashed = stepDuel(defaultDuelConfig, createDuelState(defaultDuelConfig), [duelInput("dash"), 0]);
56	    expect(dashed.fighters[0].stamina).toBe(rules.maxStamina - rules.dashStaminaCost);
57	    const hud = fakeHud();
58	    renderDuelHud(hud.root, hudModel(dashed));
59	    expect(hud.field("duel-stamina-0").dataset["value"]).toBe(String(rules.maxStamina - rules.dashStaminaCost));
60	    expect(hud.field("duel-stamina-0").style.getPropertyValue("--fill")).toBe(`${(100 * (rules.maxStamina - rules.dashStaminaCost)) / rules.maxStamina}%`);
61	    expect(hud.field("duel-stamina-1").dataset["value"]).toBe(String(rules.maxStamina));
62	    expect(hud.field("duel-stamina-1").style.getPropertyValue("--fill")).toBe("100%");
63	    // The HUD follows the state it is given: a later confirmed state with regenerated stamina redraws the bar.
64	    const later = { ...dashed, fighters: [{ ...dashed.fighters[0], stamina: 93 }, dashed.fighters[1]] as const };
65	    renderDuelHud(hud.root, hudModel(later as DuelState));
66	    expect(hud.field("duel-stamina-0").dataset["value"]).toBe("93");
67	    expect(hud.field("duel-stamina-0").style.getPropertyValue("--fill")).toBe("93%");
68	  });
69	});
70	
71	/** The fields of the duel HUD without a DOM: each `[data-testid]` lookup gets a recording stand-in. */
72	function fakeHud() {
73	  interface FakeField {
74	    textContent: string;
75	    hidden: boolean;
76	    readonly dataset: Record<string, string>;
77	    readonly style: { setProperty(name: string, value: string): void; getPropertyValue(name: string): string };
78	  }
79	  const fields = new Map<string, FakeField>();
80	  const field = (id: string): FakeField => {
81	    let found = fields.get(id);
82	    if (found === undefined) {
83	      const properties = new Map<string, string>();
84	      found = {
85	        textContent: "",
86	        hidden: false,
87	        dataset: {},
88	        style: { setProperty: (name, value) => properties.set(name, value), getPropertyValue: (name) => properties.get(name) ?? "" },
89	      };
90	      fields.set(id, found);
91	    }
92	    return found;
93	  };
94	  const root = { querySelector: (selector: string) => field(/data-testid="([^"]+)"/.exec(selector)![1]!) } as unknown as ParentNode;
95	  return { root, field };
96	}
97	
98	function hudModel(confirmed: DuelState): DuelHudModel {
99	  const { rules } = duelistMoveset;
100	  return {
101	    code: "ABC123",
102	    practice: true,
103	    phase: "fighting",
104	    status: "connected",
105	    self: 0,
106	    countdown: 0,
107	    connected: [true, true],
108	    confirmed,
109	    maxHealth: rules.maxHealth,
110	    maxStamina: rules.maxStamina,
111	    roundFrames: rules.roundFrames,
112	    overtimeFrames: rules.overtimeFrames,
113	    rttMs: 0,
114	    inputDelay: 3,
115	    corrections: 0,
116	    result: undefined,
117	  };
118	}
119	
120	describe("duel events in the view", () => {
121	  const J = duelInput("light");
122	  /** Player two one jab from a KO, 40 px from player one. */
123	  function nearKo(): DuelState {
124	    const { arena } = duelistMoveset;
125	    const centre = arena.width / 2;
126	    const state = createDuelState(defaultDuelConfig, { x: [centre - 20 * arena.subPixelsPerPixel, centre + 20 * arena.subPixelsPerPixel] });
127	    return { ...state, fighters: [state.fighters[0], { ...state.fighters[1], health: 45 }] };
128	  }
129	
130	  it("shows a hit and a KO once in the pending buffer and the arena, although a correction re-simulates them", () => {
131	    const rollback = new DuelRollback(defaultDuelConfig, 0, nearKo());
132	    const pending = new PendingDuelEvents();
133	    const arena = new ArenaFlashes();
134	    const drawn: string[] = [];
135	    const buffered: DuelFeedEvent[] = [];
136	    // The client collects every tick; the arena draws every third tick (a slow render).
137	    const tick = (frame: number) => {
138	      rollback.stepTo(frame);
139	      const fresh = rollback.drainEvents();
140	      buffered.push(...fresh);
141	      pending.collect(fresh);
142	      if (frame % 3 === 0) for (const flash of arena.add(pending.drain(), frame * 16)) drawn.push(flash.id);
143	    };
144	    rollback.setLocalInput(1, J);
145	    for (let frame = 1; frame <= 30; frame++) tick(frame);
146	    const ko = buffered.find((event) => event.result !== null)!;
147	    expect(ko.result).toMatchObject({ winner: 0, reason: "ko" });
148	    // The opponent pressed dash on the KO frame: the server's pairs differ there and every frame is stepped again.
149	    rollback.applyBundle({ frame: ko.frame, inputs: Array.from({ length: ko.frame }, (_, index) => [index === 0 ? J : 0, index === ko.frame - 1 ? duelInput("dash") : 0] as const) });
150	    expect(rollback.stats.corrections).toBe(1);
151	    for (let frame = 31; frame <= 60; frame++) tick(frame);
152	
153	    const ids = [`${ko.frame}:hit:0:jab`, `${ko.frame}:result:ko`];
154	    expect(buffered.map((event) => event.id)).toEqual(ids);
155	    expect(drawn).toEqual(ids);
156	    expect(arena.current.map((flash) => [flash.text, flash.over])).toEqual([
157	      ["-45", 1],
158	      ["K.O.", "centre"],
159	    ]);
160	  });
161	
162	  it("draws an event reported again once, and lets flashes expire", () => {
163	    const arena = new ArenaFlashes();
164	    const hit: DuelFeedEvent = { id: "9:hit:0:jab", frame: 9, event: { kind: "hit", attacker: 0, moveId: "jab", damage: 45 }, result: null };
165	    expect(arena.add([hit, hit], 100)).toHaveLength(1);
166	    expect(arena.add([hit], 200)).toEqual([]);
167	    expect(arena.expire(549)).toEqual([]);
168	    expect(arena.expire(550).map((flash) => flash.id)).toEqual([hit.id]);
169	    expect(arena.add([hit], 600)).toEqual([]);
170	  });
171	
172	  it("keeps the newest events for an arena that is not drawing (a hidden tab), each once", () => {
173	    const pending = new PendingDuelEvents(4);
174	    const event = (frame: number): DuelFeedEvent => ({ id: `${frame}:block:1:jab`, frame, event: { kind: "block", attacker: 1, moveId: "jab", damage: 0 }, result: null });
175	    pending.collect([event(1), event(2), event(3)]);
176	    pending.collect([event(4), event(5)]);
177	    expect(pending.drain().map((fresh) => fresh.frame)).toEqual([2, 3, 4, 5]);
178	    expect(pending.drain()).toEqual([]);
179	  });
180	});
181	
182	describe("dev latency setting", () => {
183	  it("reads a round trip and jitter from the query string, and nothing otherwise", () => {
184	    expect(devLatencyFromQuery("?rtt=80&jitter=20")).toEqual({ rttMs: 80, jitterMs: 20 });
185	    expect(devLatencyFromQuery("?rtt=150")).toEqual({ rttMs: 150, jitterMs: 0 });
186	    expect(devLatencyFromQuery("")).toBeUndefined();
187	    expect(devLatencyFromQuery("?rtt=abc")).toBeUndefined();
188	  });
189	
190	  beforeEach(() => {
191	    vi.useFakeTimers();
192	  });
193	
194	  afterEach(() => {
195	    vi.useRealTimers();
196	  });
197	
198	  /** The fake clock, and jitter draws taken from `draws` in turn (then from a seeded generator). */
199	  function source(draws: number[] = []): DelaySource {
200	    // mulberry32, seeded.
201	    let seed = 7;
202	    const seeded = () => {
203	      seed = (seed + 0x6d2b79f5) | 0;
204	      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
205	      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
206	      return ((t ^ (t >>> 14)) >>> 0) / 2 ** 32;
207	    };
208	    return { now: () => Date.now(), random: () => draws.shift() ?? seeded() };
209	  }
210	
211	  it("delays each item by half the round trip, give or take half the jitter", () => {
212	    const line = new DelayLine({ rttMs: 80, jitterMs: 20 }, source([0.5, 0, 0.999999]));
213	    const arrived: [string, number][] = [];
214	    const start = Date.now();
215	    line.push(() => arrived.push(["middle", Date.now() - start]));
216	    vi.advanceTimersByTime(100);
217	    line.push(() => arrived.push(["earliest", Date.now() - start - 100]));
218	    vi.advanceTimersByTime(100);
219	    line.push(() => arrived.push(["latest", Date.now() - start - 200]));
220	    vi.advanceTimersByTime(29);
221	    expect(arrived).toEqual([
222	      ["middle", 40],
223	      ["earliest", 30],
224	    ]);
225	    vi.advanceTimersByTime(100);
226	    expect(arrived.at(-1)).toEqual(["latest", 50]);
227	  });
228	
229	  it("never reorders: an item drawn earlier than the one before it waits for it", () => {
230	    // The first item draws the most delay (50 ms), the second the least (30 ms), 5 ms later.
231	    const line = new DelayLine({ rttMs: 80, jitterMs: 20 }, source([0.999999, 0]));
232	    const arrived: [number, number][] = [];
233	    const start = Date.now();
234	    line.push(() => arrived.push([1, Date.now() - start]));
235	    vi.advanceTimersByTime(5);
236	    line.push(() => arrived.push([2, Date.now() - start]));
237	    vi.advanceTimersByTime(100);
238	    expect(arrived).toEqual([
239	      [1, 50],
240	      [2, 50],
241	    ]);
242	  });
243	
244	  it("keeps every delay of a long burst within the jitter bounds and in order", () => {
245	    const line = new DelayLine({ rttMs: 80, jitterMs: 20 }, source());
246	    const delays: number[] = [];
247	    const order: number[] = [];
248	    for (let index = 0; index < 500; index++) {
249	      const sentAt = Date.now();
250	      line.push(() => {
251	        delays.push(Date.now() - sentAt);
252	        order.push(index);
253	      });
254	      vi.advanceTimersByTime(index % 3);
255	    }
256	    vi.advanceTimersByTime(1000);
257	    expect(order).toEqual(Array.from({ length: 500 }, (_, index) => index));
258	    expect(Math.min(...delays)).toBeGreaterThanOrEqual(30);
259	    expect(Math.max(...delays)).toBeLessThanOrEqual(50);
260	    // Jitter does spread them: some near each bound.
261	    expect(delays.some((delay) => delay < 34)).toBe(true);
262	    expect(delays.some((delay) => delay > 46)).toBe(true);
263	  });
264	
265	  /** A real SDK room on a stand-in socket: what it sends is recorded, and `deliver` hands it a frame from the server. */
266	  function roomOnFakeSocket() {
267	    const room = new Room("duel");
268	    const sent: { bytes: Uint8Array; at: number }[] = [];
269	    const transport = { send: (data: Uint8Array) => sent.push({ bytes: new Uint8Array(data), at: Date.now() }) };
270	    const connection = { transport, events: {} as { onmessage?: (event: unknown) => void }, isOpen: true, send: (data: Uint8Array) => connection.transport.send(data) };
271	    connection.events.onmessage = (event) => (room as unknown as { onMessageCallback(event: unknown): void }).onMessageCallback(event);
272	    (room as unknown as { connection: unknown }).connection = connection;
273	    const deliver = (bytes: Uint8Array) => connection.events.onmessage!({ data: bytes.slice().buffer });
274	    return { room, sent, deliver };
275	  }
276	
277	  /** The bytes of a server message of `type`, framed as the SDK frames room messages. */
278	  function frame(type: string, payload: unknown): Uint8Array {
279	    const encoder = roomOnFakeSocket();
280	    encoder.room.send(type, payload);
281	    return encoder.sent[0]!.bytes;
282	  }
283	
284	  it("delays the room's socket both ways, the round-trip probes included, and keeps each direction in order", () => {
285	    const { room, sent, deliver } = roomOnFakeSocket();
286	    applyDevLatency(room, { rttMs: 80, jitterMs: 20 }, source([0.5, 0.5, 0.5, 0.999999, 0]));
287	    const probes: [DuelProbe, number][] = [];
288	    const bundles: [number, number][] = [];
289	    room.onMessage(DuelMessageType.Probe, (probe: DuelProbe) => probes.push([probe, Date.now()]));
290	    room.onMessage(DuelMessageType.Frames, (bundle: { frame: number }) => bundles.push([bundle.frame, Date.now()]));
291	    const start = Date.now();
292	
293	    // A probe from the server, and the client's echo of it: each is half the round trip late.
294	    deliver(frame(DuelMessageType.Probe, { id: 1, frame: -60, rtt: 0 }));
295	    expect(probes).toEqual([]);
296	    vi.advanceTimersByTime(39);
297	    expect(probes).toEqual([]);
298	    vi.advanceTimersByTime(1);
299	    expect(probes).toEqual([[{ id: 1, frame: -60, rtt: 0 }, start + 40]]);
300	    room.send(DuelMessageType.Probe, { id: 1 });
301	    expect(sent).toEqual([]);
302	    vi.advanceTimersByTime(40);
303	    expect(sent.map((item) => item.at - start)).toEqual([80]);
304	    // It is the echo itself, unchanged, and it leaves a full round trip after the probe left the server.
305	    expect(sent[0]!.bytes).toEqual(frame(DuelMessageType.Probe, { id: 1 }));
306	
307	    // Input goes out delayed too.
