2	import { createDuelState, defaultDuelConfig as config, duelInput as I, hashState, replayDuel, stepDuel, type DuelState, type PlayerIndex } from "../duel/index.js";
3	import {
4	  BUNDLE_FRAMES,
5	  CATCH_UP_FRAMES,
6	  chooseInputDelay,
7	  DuelAuthority,
8	  DuelClientSession,
9	  DuelClock,
10	  DuelEventFeed,
11	  DuelRollback,
12	  duelEventId,
13	  FRAME_MS,
14	  HELD_INPUT_FRAMES,
15	  HISTORY_FRAMES,
16	  inputDelayFromSamples,
17	  INPUTS_PER_MESSAGE,
18	  linkStats,
19	  MAX_INPUT_DELAY,
20	  MESSAGES_PER_SECOND,
21	  MIN_INPUT_DELAY,
22	  RESYNC_FRAMES,
23	  type AuthorityBundle,
24	  type OutgoingDuelInput,
25	} from "./index.js";
26	
27	const { fighter: body, arena } = config.moveset;
28	const R = I("right");
29	const L = I("left");
30	const J = I("light");
31	const K = I("heavy");
32	
33	/** The fighters `gapPx` pixels apart about the arena's centre. */
34	function closeDuel(gapPx: number): DuelState {
35	  const centre = arena.width / 2;
36	  const gap = gapPx * arena.subPixelsPerPixel;
37	  return createDuelState(config, { x: [centre - gap / 2, centre + gap / 2] });
38	}
39	
40	/** The fighters `gapPx` apart, player two with `health` left: a jab (45) at that range is a KO. */
41	function nearKo(gapPx: number, health = 45): DuelState {
42	  const state = closeDuel(gapPx);
43	  return { ...state, fighters: [state.fighters[0], { ...state.fighters[1], health }] };
44	}
45	
46	/** What each player holds at a client frame (before the input delay). */
47	type Script = (clientFrame: number) => number;
48	
49	interface NetworkResult {
50	  readonly authority: DuelAuthority;
51	  readonly clients: readonly [DuelRollback, DuelRollback];
52	}
53	
54	/**
55	 * A lockstep model of the duel network in whole frames: both clients run on the server's frame, tag the input held
56	 * at frame c for c + delay, send the last four tagged frames every second frame, and the messages and bundles arrive
57	 * `up` and `down` frames later. Everything is deterministic, so exact counts can be asserted.
58	 */
59	function network(options: { initial: DuelState; delay: number; up: number; down: number; frames: number; scripts: readonly [Script, Script] }): NetworkResult {
60	  const authority = new DuelAuthority(config, options.initial);
61	  const clients = [new DuelRollback(config, 0, options.initial), new DuelRollback(config, 1, options.initial)] as const;
62	  const toServer: { at: number; player: PlayerIndex; message: OutgoingDuelInput }[] = [];
63	  const toClients: { at: number; bundle: AuthorityBundle }[] = [{ at: options.down, bundle: authority.snapshotBundle() }];
64	  const seq = [0, 0];
65	  // During the countdown each client tagged and sent the first frames of the fight, with nothing held.
66	  for (const player of [0, 1] as const) {
67	    for (let early = 1; early < options.delay; early++) clients[player].setLocalInput(early, 0);
68	    for (let last = 2; last < options.delay + 1; last += 2) {
69	      const frame = Math.min(last, options.delay - 1);
70	      const inputs = Array.from({ length: Math.min(4, frame) }, () => 0);
71	      toServer.push({ at: 0, player, message: { seq: ++seq[player]!, frame, inputs } });
72	    }
73	  }
74	  for (let frame = 1; frame <= options.frames; frame++) {
75	    // Clients: tag and send, as of the previous frame (the one they are on when the server steps this one).
76	    for (const player of [0, 1] as const) {
77	      const client = clients[player];
78	      const tagged = frame - 1 + options.delay;
79	      client.setLocalInput(tagged, options.scripts[player](frame - 1));
80	      if (frame % 2 === 1) {
81	        const first = Math.max(1, tagged - 3);
82	        const inputs = Array.from({ length: tagged - first + 1 }, (_, index) => client.localInput(first + index) ?? 0);
83	        toServer.push({ at: frame + options.up, player, message: { seq: ++seq[player]!, frame: tagged, inputs } });
84	      }
85	    }
86	    // Server: the messages due, then the step.
87	    for (const item of toServer.filter((entry) => entry.at <= frame)) authority.receive(item.player, item.message.frame, item.message.inputs);
88	    toServer.splice(0, toServer.filter((entry) => entry.at <= frame).length);
89	    const bundle = authority.step();
90	    if (bundle !== undefined) toClients.push({ at: frame + options.down, bundle });
91	    // Clients: the bundles due, then predict up to this frame.
92	    const due = toClients.filter((entry) => entry.at <= frame);
93	    toClients.splice(0, due.length);
94	    for (const client of clients) {
95	      for (const entry of due) client.applyBundle(entry.bundle);
96	      client.stepTo(frame);
97	    }
98	  }
99	  // Drain the network so every frame is confirmed.
100	  for (const client of clients) for (const entry of toClients) client.applyBundle(entry.bundle);
101	  return { authority, clients };
102	}
