422	/** A client session driven by a fake clock at an exact 60 Hz, with the server's probes and bundles fed in. */
423	function sessionRig(options: { player?: PlayerIndex; initial?: DuelState; delay?: number } = {}) {
424	  const initial = options.initial ?? closeDuel(40);
425	  const session = new DuelClientSession({ config, player: options.player ?? 0, initial });
426	  session.inputDelay = options.delay ?? 3;
427	  // The server's frame 0 is at local time 1000 and the link is instant: messages arrive on a frame's edge, and the
428	  // client ticks in the middle of a frame.
429	  const edge = (frame: number) => 1000 + frame * FRAME_MS;
430	  const at = (frame: number) => edge(frame) + FRAME_MS / 2;
431	  session.receiveProbe({ frame: -60, rtt: 0 }, edge(-60));
432	  const sent: OutgoingDuelInput[] = [];
433	  const sentAt: number[] = [];
434	  const tick = (now: number, bits: number) => {
435	    const message = session.tick(now, bits);
436	    if (message === undefined) return;
437	    sent.push(message);
438	    sentAt.push(now);
