1	import { randomInt } from "node:crypto";
2	import { performance } from "node:perf_hooks";
3	import { ErrorCode, matchMaker, Room, ServerError, type AuthContext, type Client } from "colyseus";
4	import {
5	  createDuelOptionsSchema,
6	  DUEL_CODE_REQUIRED_MESSAGE,
7	  DUEL_COUNTDOWN_FRAMES,
8	  DUEL_RECONNECT_SECONDS,
9	  DUEL_ROOM,
10	  DUEL_UNAVAILABLE_MESSAGE,
11	  duelFullMessage,
12	  DuelMessageType,
13	  duelPracticeMessageSchema,
14	  duelProbeReplySchema,
15	  joinDuelOptionsSchema,
16	  JoinRefusal,
17	  MAX_INPUT_MESSAGES_PER_SECOND,
18	  NO_SUCH_DUEL_MESSAGE,
19	  PROTOCOL_VERSION,
20	  type DuelEndReason,
21	  type DuelProbe,
22	  type DuelRoomPhase,
23	  type DummyBehaviour,
24	} from "@pirate-sea-race/protocol";
25	import { createDuelState, defaultDuelConfig, duelInput, type DuelState, type PlayerIndex } from "@pirate-sea-race/simulation/duel";
26	import { DuelAuthority, inputDelayFromSamples, linkStats, type AuthorityStats } from "@pirate-sea-race/simulation/netcode";
27	import { admitSeat, authorizePrivateEntry, type AdmissionRules } from "./admission.js";
28	import { DuelInputGate } from "./duelInputGate.js";
29	import type { MatchMetadata } from "./MatchRoom.js";
30	import { generateMatchCode } from "./matchCode.js";
31	import { DuelRoomStateSchema, DuelSeatSchema } from "./schema.js";
32	
33	const STEPS_PER_SECOND = 60;
34	/** The lobby state goes out at 20 Hz; the duel's frames travel as messages. */
35	const PATCH_INTERVAL_MS = 1000 / 20;
36	/** Round-trip probes: every 6 frames during the countdown (for the input delay), every 30 during the fight (the HUD). */
37	const COUNTDOWN_PROBE_FRAMES = 6;
38	const FIGHT_PROBE_FRAMES = 30;
39	/** Round-trip samples kept per seat. */
40	const PROBE_SAMPLES = 25;
41	/** The input delay is chosen this many frames before the countdown ends, from the probes measured until then. */
42	export const DELAY_DECISION_FRAMES = 30;
43	
44	/** A duel's admission: the `duel` listing, the duel option schemas and the duel refusal messages. */
45	const DUEL_ADMISSION: AdmissionRules = {
46	  roomName: DUEL_ROOM,
47	  createSchema: createDuelOptionsSchema,
48	  joinSchema: joinDuelOptionsSchema,
49	  noSuchMessage: NO_SUCH_DUEL_MESSAGE,
50	  codeRequiredMessage: DUEL_CODE_REQUIRED_MESSAGE,
51	  fullMessage: duelFullMessage,
52	};
53	
54	/** Checks a create or join request for a duel before matchmaking places it (see `authorizePrivateEntry`). */
55	export function authorizeDuelEntry(options: unknown): Promise<true> {
56	  return authorizePrivateEntry(options, DUEL_ADMISSION);
57	}
58	
59	interface Seat {
60	  readonly slot: PlayerIndex;
61	  readonly gate: DuelInputGate;
62	  readonly schema: DuelSeatSchema;
63	  /** Probe ids in flight and when they were sent (performance.now()). */
64	  readonly probes: Map<number, number>;
65	  readonly rtts: number[];
66	  nextProbe: number;
67	}
68	
69	/** What the room reports to tests and diagnostics about a finished or running duel. */
70	export interface DuelDiagnostics {
71	  readonly phase: DuelRoomPhase;
72	  readonly frame: number;
73	  readonly inputDelay: number;
74	  readonly authority: AuthorityStats;
75	  /** Input messages the gate dropped, per slot and reason. */
76	  readonly dropped: Record<string, DuelInputGate["dropped"]>;
77	  readonly rttSamples: Record<string, readonly number[]>;
78	}
79	
80	/**
81	 * One standalone duel (the combat spike, §18 stage 1), privately admitted like a match: created with a one-time token,
82	 * joined by its code, two players (or one against the server's dummy in practice). The countdown starts once every
83	 * seat is taken; during it the room probes both round trips and, DELAY_DECISION_FRAMES before the end, chooses the
84	 * shared input delay. It then steps `stepDuel` at 60 Hz through `DuelAuthority` (first copy of each frame's input
85	 * wins, late input never rewrites a frame, the held input repeats for 250 ms and then neutral) and broadcasts a frame
86	 * bundle every third frame. The step's result ends the duel, and so does a forfeit (a player who quits, or stays absent
87	 * past DUEL_RECONNECT_SECONDS), decided at the next frame boundary together with any other forfeit on that frame.
88	 */
89	export class DuelRoom extends Room<{ state: DuelRoomStateSchema; metadata: MatchMetadata }> {
90	  override maxClients = 2;
91	  /** A flood ceiling: past it Colyseus disconnects the client. Excess input is dropped well below it, in the gate. */
92	  override maxMessagesPerSecond = MAX_INPUT_MESSAGES_PER_SECOND * 4;
93	  override patchRate = PATCH_INTERVAL_MS;
94	  override state = new DuelRoomStateSchema();
95	
96	  private readonly config = defaultDuelConfig;
97	  private authority!: DuelAuthority;
98	  private readonly seats = new Map<string, Seat>();
99	  private createToken: string | undefined;
100	  private tick = 0;
101	  /** Players who left for good (quit, or absent past the reconnection window) since the last frame boundary. */
102	  private readonly forfeits = new Set<PlayerIndex>();
103	
104	  static override async onAuth(_token: string, options: unknown, _context: AuthContext): Promise<true> {
105	    return authorizeDuelEntry(options);
106	  }
107	
108	  override async onCreate(options: unknown): Promise<void> {
109	    const parsed = createDuelOptionsSchema.safeParse(options);
110	    if (!parsed.success) throw new ServerError(ErrorCode.MATCHMAKE_INVALID_CRITERIA, DUEL_UNAVAILABLE_MESSAGE);
111	    this.createToken = parsed.data.createToken;
112	    const practice = parsed.data.practice === true;
113	    this.maxClients = practice ? 1 : 2;
114	    const code = await this.allocateCode();
115	    const seed = randomInt(0, 2 ** 32);
116	    this.authority = new DuelAuthority(this.config, createDuelState(this.config, { seed }));
117	    this.state.code = code;
118	    this.state.protocolVersion = PROTOCOL_VERSION;
119	    this.state.practice = practice;
120	    this.state.dummy = practice ? "idle" : "";
121	    this.state.phase = "waiting";
122	    this.state.countdown = DUEL_COUNTDOWN_FRAMES;
123	    this.state.seed = seed;
124	    this.state.winner = -1;
125	    if (practice) this.authority.script(1, (state) => this.dummyInput(state));
126	    // As for matches: the create request's token was copied into the listing; replacing the metadata drops it.
127	    await this.setMatchmaking({ metadata: { code, custom: true } });
128	
129	    this.onMessage(DuelMessageType.Input, (client, message: unknown) => this.receiveInput(client, message));
130	    this.onMessage(DuelMessageType.Probe, (client, message: unknown) => this.receiveProbeReply(client, message));
131	    this.onMessage(DuelMessageType.Practice, (_client, message: unknown) => {
132	      const request = duelPracticeMessageSchema.safeParse(message);
133	      if (this.state.practice && request.success) this.state.dummy = request.data.dummy;
134	    });
135	    // Unknown message types are dropped, not answered: Colyseus would otherwise disconnect the sender.
136	    this.onMessage("*", () => undefined);
137	    this.setFixedTimestep(() => this.advance(), STEPS_PER_SECOND);
138	  }
139	
140	  override onJoin(client: Client, options: unknown): void {
141	    this.createToken = admitSeat(options, { code: this.state.code, createToken: this.createToken }, DUEL_ADMISSION);
142	    const taken = new Set([...this.seats.values()].map((seat) => seat.slot));
143	    const slot: PlayerIndex = taken.has(0) ? 1 : 0;
144	    const schema = new DuelSeatSchema();
145	    schema.sessionId = client.sessionId;
146	    schema.slot = slot;
147	    schema.connected = true;
148	    this.state.seats.push(schema);
149	    this.seats.set(client.sessionId, { slot, gate: new DuelInputGate(), schema, probes: new Map(), rtts: [], nextProbe: 1 });
150	    if (this.state.phase === "waiting" && this.seats.size === this.maxClients) {
151	      this.state.phase = "countdown";
152	      void this.lock();
153	    }
154	  }
155	
156	  /** A player dropped without leaving: their seat is kept for DUEL_RECONNECT_SECONDS, then they forfeit (§12). */
157	  override onDrop(client: Client): void {
158	    const seat = this.seats.get(client.sessionId);
159	    if (seat === undefined || this.state.phase === "over") return;
160	    seat.schema.connected = false;
161	    seat.probes.clear();
162	    void this.allowReconnection(client, DUEL_RECONNECT_SECONDS).catch(() => undefined);
163	  }
164	
165	  /** The same player is back: they continue from the authoritative state, which a snapshot bundle gives them. */
166	  override onReconnect(client: Client): void {
167	    const seat = this.seats.get(client.sessionId);
168	    if (seat === undefined) return;
169	    seat.schema.connected = true;
170	    if (this.state.phase === "fighting" || this.state.phase === "over") client.send(DuelMessageType.Frames, this.authority.snapshotBundle());
171	  }
172	
173	  /** A player left for good (quit, or absent past the reconnection window): before the countdown their seat frees up. */
174	  override onLeave(client: Client): void {
175	    const seat = this.seats.get(client.sessionId);
176	    if (seat === undefined) return;
177	    seat.schema.connected = false;
178	    if (this.state.phase === "waiting") {
179	      this.seats.delete(client.sessionId);
180	      const index = this.state.seats.findIndex((entry) => entry.sessionId === client.sessionId);
181	      if (index >= 0) this.state.seats.splice(index, 1);
182	      return;
183	    }
184	    // Forfeits are decided together at the next frame boundary (§12), so the order in which two leaves are processed
185	    // can never pick a winner.
186	    if (this.state.phase === "countdown" || this.state.phase === "fighting") this.forfeits.add(seat.slot);
187	  }
188	
189	  /** Inputs dropped per client and reason, for tests and diagnostics. */
190	  droppedInputs(sessionId: string): DuelInputGate["dropped"] | undefined {
191	    return this.seats.get(sessionId)?.gate.dropped;
192	  }
193	
194	  /** The duel's counters, for tests and the harness. */
195	  diagnostics(): DuelDiagnostics {
196	    const bySlot = <T>(pick: (seat: Seat) => T) => Object.fromEntries([...this.seats.values()].map((seat) => [String(seat.slot), pick(seat)]));
197	    return {
198	      phase: this.state.phase as DuelRoomPhase,
199	      frame: this.authority.frame,
200	      inputDelay: this.state.inputDelay,
201	      authority: structuredClone(this.authority.stats),
202	      dropped: bySlot((seat) => ({ ...seat.gate.dropped })),
203	      rttSamples: bySlot((seat) => [...seat.rtts]),
204	    };
205	  }
206	
207	  /** The authoritative duel state, for tests. */
208	  get duelState(): DuelState {
209	    return this.authority.state;
210	  }
211	
212	  /** Every input pair applied so far as a replayable log, for tests. */
213	  inputLog(): ReturnType<DuelAuthority["inputLog"]> {
214	    return this.authority.inputLog();
215	  }
216	
217	  /** The duel's frame on one timeline: negative during the countdown, then the frames stepped. */
218	  private get serverFrame(): number {
219	    return this.state.phase === "countdown" || this.state.phase === "waiting" ? -this.state.countdown : this.authority.frame;
220	  }
221	
222	  private receiveInput(client: Client, message: unknown): void {
223	    const seat = this.seats.get(client.sessionId);
224	    if (seat === undefined || (this.state.phase !== "countdown" && this.state.phase !== "fighting")) return;
225	    const input = seat.gate.receive(message, this.tick, this.serverFrame);
226	    if (input === undefined || (this.state.practice && seat.slot !== 0)) return;
227	    this.authority.receive(seat.slot, input.frame, input.inputs);
228	  }
229	
230	  private receiveProbeReply(client: Client, message: unknown): void {
231	    const seat = this.seats.get(client.sessionId);
232	    const reply = duelProbeReplySchema.safeParse(message);
233	    if (seat === undefined || !reply.success) return;
234	    const sentAt = seat.probes.get(reply.data.id);
235	    if (sentAt === undefined) return;
236	    seat.probes.delete(reply.data.id);
237	    seat.rtts.push(performance.now() - sentAt);
238	    if (seat.rtts.length > PROBE_SAMPLES) seat.rtts.shift();
239	    seat.schema.rtt = Math.round(linkStats(seat.rtts)!.rttMs);
240	  }
241	
242	  private sendProbes(): void {
243	    for (const client of this.clients) {
244	      const seat = this.seats.get(client.sessionId);
245	      if (seat === undefined || !seat.schema.connected) continue;
246	      const id = seat.nextProbe++;
247	      seat.probes.set(id, performance.now());
248	      // Probes that never came back (a dropped connection) are forgotten after a few seconds' worth.
249	      for (const old of seat.probes.keys()) if (old < id - 20) seat.probes.delete(old);
250	      const probe: DuelProbe = { id, frame: this.serverFrame, rtt: seat.rtts.length === 0 ? 0 : linkStats(seat.rtts)!.rttMs };
251	      client.send(DuelMessageType.Probe, probe);
252	    }
253	  }
254	
255	  private advance(): void {
256	    this.tick++;
