261	        if (this.state.countdown % COUNTDOWN_PROBE_FRAMES === 0) this.sendProbes();
262	        if (this.state.countdown === DELAY_DECISION_FRAMES) {
263	          this.state.inputDelay = inputDelayFromSamples([...this.seats.values()].map((seat) => seat.rtts));
264	        }
265	        if (this.state.countdown === 0) {
266	          this.state.phase = "fighting";
267	          this.broadcast(DuelMessageType.Frames, this.authority.snapshotBundle());
268	        }
269	        return;
270	      case "fighting": {
271	        const bundle = this.authority.step();
272	        if (bundle !== undefined) this.broadcast(DuelMessageType.Frames, bundle);
273	        if (this.authority.frame % FIGHT_PROBE_FRAMES === 0) this.sendProbes();
