299	  private finish(winner: PlayerIndex | null, reason: DuelEndReason, frame: number): void {
300	    if (this.state.phase === "over") return;
301	    this.state.phase = "over";
302	    this.state.winner = winner ?? -1;
303	    this.state.reason = reason;
304	    this.state.resultFrame = frame;
305	  }
