1	import { connect, createServer, type AddressInfo, type Socket } from "node:net";
2	import { afterEach, describe, expect, it } from "vitest";
3	import { ImpairmentProxy, type Impairment } from "./impairmentProxy.js";
4	
5	/** An unmasked WebSocket binary frame carrying `index` as its one-byte payload. */
6	const frame = (index: number) => Buffer.from([0x82, 0x01, index]);
7	
8	const cleanups: (() => Promise<void> | void)[] = [];
9	
10	afterEach(async () => {
11	  for (const cleanup of cleanups.splice(0).reverse()) await cleanup();
12	});
13	
14	/**
15	 * A server that answers any upgrade with 101 and then sends `count` one-byte frames, one every `spacingMs`; a client
16	 * that connects through the proxy and records when each frame arrives.
17	 */
18	async function stream(impairment: Impairment, seed: number, count: number, spacingMs: number): Promise<{ index: number; sentAt: number; at: number }[]> {
19	  const sentAt: number[] = [];
20	  const target = createServer((socket: Socket) => {
21	    socket.once("data", () => {
22	      socket.write("HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n\r\n");
23	      let index = 0;
24	      const timer = setInterval(() => {
25	        sentAt.push(performance.now());
26	        socket.write(frame(index++));
27	        if (index === count) clearInterval(timer);
28	      }, spacingMs);
29	      socket.on("close", () => clearInterval(timer));
30	    });
31	  });
32	  await new Promise<void>((resolve) => target.listen(0, "127.0.0.1", resolve));
33	  cleanups.push(() => new Promise<void>((resolve) => target.close(() => resolve())));
34	  const proxy = await ImpairmentProxy.start((target.address() as AddressInfo).port, impairment, seed);
35	  cleanups.push(() => proxy.close());
36	
37	  const port = Number(new URL(proxy.endpoint).port);
38	  const client = connect(port, "127.0.0.1");
39	  cleanups.push(() => void client.destroy());
40	  const arrivals: { index: number; sentAt: number; at: number }[] = [];
41	  let head = true;
42	  let pending = Buffer.alloc(0);
43	  await new Promise<void>((resolve) => {
44	    client.on("data", (chunk: Buffer) => {
45	      pending = Buffer.concat([pending, chunk]);
46	      if (head) {
47	        const end = pending.indexOf("\r\n\r\n");
48	        if (end < 0) return;
49	        pending = pending.subarray(end + 4);
50	        head = false;
51	      }
52	      while (pending.length >= 3) {
53	        const index = pending[2]!;
54	        arrivals.push({ index, sentAt: sentAt[index]!, at: performance.now() });
55	        pending = pending.subarray(3);
56	      }
57	      if (arrivals.length === count) resolve();
58	    });
59	    client.write("GET / HTTP/1.1\r\nHost: x\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n\r\n");
60	  });
61	  return arrivals;
62	}
63	
64	describe("ImpairmentProxy", () => {
